import{_ as o,a as r,b as t}from"./chunks/completed.B5AU_Dhd.js";import{_ as a,c as i,o as n,ae as s}from"./chunks/framework.DBgX5bsf.js";const _=JSON.parse('{"title":"Order Management in Drupal Commerce","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/commerce/commandes.md","filePath":"en/docs/commerce/commandes.md"}'),l={name:"en/docs/commerce/commandes.md"};function d(c,e,m,h,u,p){return n(),i("div",null,e[0]||(e[0]=[s('<h1 id="order-management-in-drupal-commerce" tabindex="-1">Order Management in Drupal Commerce <a class="header-anchor" href="#order-management-in-drupal-commerce" aria-label="Permalink to &quot;Order Management in Drupal Commerce&quot;">​</a></h1><p>Order management is a crucial step in the operation of an e-commerce platform. It allows you to track, process, and ship orders efficiently. In Drupal Commerce, orders are managed via the <strong>Orders</strong> tab in the administration interface. Here is a detailed guide to processing orders after a purchase on your site.</p><h2 id="accessing-the-order-list" tabindex="-1"><strong>Accessing the Order List</strong> <a class="header-anchor" href="#accessing-the-order-list" aria-label="Permalink to &quot;**Accessing the Order List**&quot;">​</a></h2><p>To access the list of orders, follow these steps:</p><ol><li>Go to the <strong>Commerce</strong> -&gt; <strong>Orders</strong> menu.</li><li>You will see a list of all orders placed on your site.</li></ol><h2 id="viewing-order-details" tabindex="-1"><strong>Viewing Order Details</strong> <a class="header-anchor" href="#viewing-order-details" aria-label="Permalink to &quot;**Viewing Order Details**&quot;">​</a></h2><p>To view the details of a specific order:</p><ol><li>Click on the <strong>View</strong> link corresponding to the desired order.</li><li>You will have access to all information related to the order, including products, customer information, shipping, and billing details.</li></ol><h2 id="processing-an-order" tabindex="-1"><strong>Processing an Order</strong> <a class="header-anchor" href="#processing-an-order" aria-label="Permalink to &quot;**Processing an Order**&quot;">​</a></h2><p>Processing an order involves several key steps:</p><h3 id="_1-order-verification" tabindex="-1"><strong>1. Order Verification</strong> <a class="header-anchor" href="#_1-order-verification" aria-label="Permalink to &quot;**1. Order Verification**&quot;">​</a></h3><ul><li><p>Verify the ordered products, customer information, shipping, and billing details.</p></li><li><p>If everything is correct, click <strong>Validate order</strong> to confirm the order.</p><p><img src="'+o+'" alt="Validate order"></p></li></ul><h3 id="_2-transition-to-the-fulfillment-state" tabindex="-1"><strong>2. Transition to the &#39;Fulfillment&#39; State</strong> <a class="header-anchor" href="#_2-transition-to-the-fulfillment-state" aria-label="Permalink to &quot;**2. Transition to the &#39;Fulfillment&#39; State**&quot;">​</a></h3><ul><li><p>Once the order is validated, its status changes to <strong>Fulfillment</strong>. This means the order is ready to be prepared and shipped.</p><p><img src="'+r+'" alt="Fulfillment"></p></li></ul><h3 id="_3-transition-to-the-completed-state" tabindex="-1"><strong>3. Transition to the &#39;Completed&#39; State</strong> <a class="header-anchor" href="#_3-transition-to-the-completed-state" aria-label="Permalink to &quot;**3. Transition to the &#39;Completed&#39; State**&quot;">​</a></h3><ul><li><p>When the order is shipped and delivered, change its status to <strong>Completed</strong>. This indicates that the processing is complete.</p><p><img src="'+t+'" alt="Completed"></p></li></ul><h2 id="other-possible-actions-on-an-order" tabindex="-1"><strong>Other Possible Actions on an Order</strong> <a class="header-anchor" href="#other-possible-actions-on-an-order" aria-label="Permalink to &quot;**Other Possible Actions on an Order**&quot;">​</a></h2><p>In addition to the processing steps, you can perform the following actions on an order:</p><h3 id="_1-update-the-order-status" tabindex="-1"><strong>1. Update the Order Status</strong> <a class="header-anchor" href="#_1-update-the-order-status" aria-label="Permalink to &quot;**1. Update the Order Status**&quot;">​</a></h3><ul><li>You can update the order status based on its progress (e.g., pending, processing, shipped, etc.).</li></ul><h3 id="_2-add-comments" tabindex="-1"><strong>2. Add Comments</strong> <a class="header-anchor" href="#_2-add-comments" aria-label="Permalink to &quot;**2. Add Comments**&quot;">​</a></h3><ul><li>Add comments to track the order&#39;s progress and facilitate internal communication.</li></ul><h3 id="_3-add-products" tabindex="-1"><strong>3. Add Products</strong> <a class="header-anchor" href="#_3-add-products" aria-label="Permalink to &quot;**3. Add Products**&quot;">​</a></h3><ul><li>If necessary, you can add additional products to the order.</li></ul><h3 id="_4-modify-shipping-information" tabindex="-1"><strong>4. Modify Shipping Information</strong> <a class="header-anchor" href="#_4-modify-shipping-information" aria-label="Permalink to &quot;**4. Modify Shipping Information**&quot;">​</a></h3><ul><li>You can adjust shipping information, such as the address or delivery method.</li></ul><h3 id="_5-modify-billing-information" tabindex="-1"><strong>5. Modify Billing Information</strong> <a class="header-anchor" href="#_5-modify-billing-information" aria-label="Permalink to &quot;**5. Modify Billing Information**&quot;">​</a></h3><ul><li>You can update billing information if needed.</li></ul><h3 id="_6-modify-customer-information" tabindex="-1"><strong>6. Modify Customer Information</strong> <a class="header-anchor" href="#_6-modify-customer-information" aria-label="Permalink to &quot;**6. Modify Customer Information**&quot;">​</a></h3><ul><li>You can update customer information, such as name, address, or contact details.</li></ul><h4 id="official-documentation" tabindex="-1"><strong>Official Documentation</strong> <a class="header-anchor" href="#official-documentation" aria-label="Permalink to &quot;**Official Documentation**&quot;">​</a></h4><p>To learn more about order management in Drupal Commerce, consult the official documentation:</p><ul><li><a href="https://docs.drupalcommerce.org/v2/developer-guide/orders/workflows/" target="_blank" rel="noreferrer">Drupal Commerce - Order Workflows</a></li></ul>',33)]))}const b=a(l,[["render",d]]);export{_ as __pageData,b as default};
